import{_ as n,C as o,o as i,c,j as t,a as d,E as a,ag as l}from"./chunks/framework.HG0H2VLS.js";const y=JSON.parse('{"title":"RoomCard","description":"","frontmatter":{},"headers":[],"relativePath":"components/room-card.md","filePath":"components/room-card.md"}'),h={name:"components/room-card.md"},p={id:"roomcard",tabindex:"-1"};function g(m,e,u,b,f,w){const s=o("Badge"),r=o("ComponentDemo");return i(),c("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-roomcard",tabindex:"-1"},[d("title: RoomCard "),t("a",{class:"header-anchor",href:"#title-roomcard","aria-label":'Permalink to "title: RoomCard"'},"​")],-1)),t("h1",p,[e[0]||(e[0]=d("RoomCard ",-1)),a(s,{type:"info",text:"Design System"}),e[1]||(e[1]=d()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#roomcard","aria-label":'Permalink to "RoomCard <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"Seating Planner room/plan card")],-1)),a(r,{src:"/demos/src/components/RoomCard/RoomCard.html"}),e[6]||(e[6]=l('<h2 id="variant-matrix-12-variants" tabindex="-1">Variant matrix (12 variants) <a class="header-anchor" href="#variant-matrix-12-variants" aria-label="Permalink to &quot;Variant matrix (12 variants)&quot;">​</a></h2><p>Axes are <strong>Tier × Type × State × Device</strong>. Tier is single-valued (<code>Component</code>) and produces no CSS. Device is a media query, not a modifier — so the 12 Figma variants collapse to 4 CSS classes.</p><table tabindex="0"><thead><tr><th>Type</th><th>State</th><th>Device</th><th>Node</th><th>CSS</th></tr></thead><tbody><tr><td>Default</td><td>Default</td><td>Desktop</td><td><code>3470:84950</code></td><td><code>.room-card</code></td></tr><tr><td>Default</td><td>Selected</td><td>Desktop</td><td><code>3474:90673</code></td><td><code>+ .room-card--selected</code></td></tr><tr><td>Seats Assigned</td><td>Default</td><td>Desktop</td><td><code>3470:84949</code></td><td><code>.room-card</code> (data only — see below)</td></tr><tr><td>Seats Assigned</td><td>Selected</td><td>Desktop</td><td><code>3470:84948</code></td><td><code>+ .room-card--selected</code></td></tr><tr><td>Full</td><td>Default</td><td>Desktop</td><td><code>3470:84952</code></td><td><code>+ .room-card--full</code></td></tr><tr><td>Full</td><td>Selected</td><td>Desktop</td><td><code>3474:90688</code></td><td><code>+ .room-card--full.room-card--selected</code></td></tr><tr><td>Default</td><td>Default</td><td>Mobile</td><td><code>3484:186665</code></td><td><code>@media (max-width: 767px)</code></td></tr><tr><td>Default</td><td>Selected</td><td>Mobile</td><td><code>3484:186691</code></td><td>↑ + <code>--selected</code></td></tr><tr><td>Seats Assigned</td><td>Default</td><td>Mobile</td><td><code>3484:186701</code></td><td>↑</td></tr><tr><td>Seats Assigned</td><td>Selected</td><td>Mobile</td><td><code>3484:186712</code></td><td>↑ + <code>--selected</code></td></tr><tr><td>Full</td><td>Default</td><td>Mobile</td><td><code>3484:186649</code></td><td>↑ + <code>--full</code></td></tr><tr><td>Full</td><td>Selected</td><td>Mobile</td><td><code>3484:186675</code></td><td>↑ + <code>--full</code> + <code>--selected</code></td></tr></tbody></table><p>Desktop is 290×93 as drawn, mobile 291.5×85. Rendered heights are 95 / 87 — Figma strokes are inside-aligned and don&#39;t add to the frame size, whereas a <code>box-sizing: border-box</code> element counts its 1px border. The card is auto-height in a list, so this is cosmetic arithmetic, not a bug.</p><h3 id="type-default-and-type-seats-assigned-are-the-same-css" tabindex="-1">Type=Default and Type=Seats Assigned are the same CSS <a class="header-anchor" href="#type-default-and-type-seats-assigned-are-the-same-css" aria-label="Permalink to &quot;Type=Default and Type=Seats Assigned are the same CSS&quot;">​</a></h3><p>They differ <strong>only in data</strong>: <code>0/148</code> vs <code>124/148</code> (so 0% vs 84% bar) and <code>148 seats free</code> vs <code>24 seats free</code>. Both labels are brand-coloured; both bars are brand-filled. No CSS branches on this, so there is deliberately no <code>.room-card--seats-assigned</code> — an empty modifier would be dead code. <code>Full</code> is the only Type that earns a class.</p><h3 id="the-seats-assigned-bar-in-figma-is-drawn-not-computed" tabindex="-1">The Seats Assigned bar in Figma is drawn, not computed <a class="header-anchor" href="#the-seats-assigned-bar-in-figma-is-drawn-not-computed" aria-label="Permalink to &quot;The Seats Assigned bar in Figma is drawn, not computed&quot;">​</a></h3><p>Figma sets the fill to a fixed <code>w-[158px]</code>, which is ~62% of the track — while the label beside it says <code>124/148</code>, i.e. 84%. The two disagree in Figma. <strong>Never port the 158px.</strong> The fill is driven by <code>--room-card-progress</code>, which the parent computes as <code>seatsSeated / seatsCapacity</code>.</p><h2 id="what-this-represents" tabindex="-1">What this represents <a class="header-anchor" href="#what-this-represents" aria-label="Permalink to &quot;What this represents&quot;">​</a></h2><p>Confirmed with the designer 2026-08-25: <strong>a Room Card IS a room/plan card</strong> — the componentised form of the Seating Planner&#39;s plan chip, not a new entity above <code>SeatingPlan</code>. Its content is the same summary the prototype&#39;s chip already renders (<code>N tables · X/Y seated</code>, <code>Z free</code>, fill bar), so no new table is needed on the backend; the counts derive from the plan&#39;s tables and seats.</p><p>Two consequences:</p><ul><li><code>docs/handover-manifest.json</code> → <code>seating-room-list</code> records the contract against <code>SeatingPlan</code> rather than a new Room entity.</li><li>The prototype at <code>src/prototypes/SeatingPlanner/</code> still renders its own hand-built plan chip. <strong>This component is now the authority</strong> — the chip should be replaced by it so the two cannot drift. Not done here (the prototype is parked and uncommitted); flagged as a follow-up.</li></ul><h2 id="interaction-model" tabindex="-1">Interaction model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction model&quot;">​</a></h2><p>Confirmed with the designer 2026-08-25:</p><ul><li><strong>Presentational only.</strong> The parent module owns selection and toggles <code>.room-card--selected</code>. Single-select coordination (only one room active) belongs to whoever renders the list, not here.</li><li><strong>The whole card is the select trigger.</strong> <code>.room-card__select</code> is a real <code>&lt;button&gt;</code> wrapping the room name, with an <code>::after</code> stretched over the card via <code>position: absolute; inset: 0</code>. <code>.room-card__actions</code> is raised on <code>z-index: 1</code> so edit and delete stay independently clickable inside the larger hit area. Verified by hit-testing: the card&#39;s bottom-centre resolves to <code>.room-card__select</code>, the edit button&#39;s centre resolves to its own icon.</li><li><strong>Focus is drawn on the card, not the name.</strong> A <code>:focus-visible</code> ring on the button alone would outline just the text run while the clickable area is the whole card, so <code>.room-card:has(.room-card__select:focus-visible)</code> moves the ring out to the card and the button&#39;s own outline is suppressed.</li><li>Edit and delete are real <code>&lt;button&gt;</code>s with <code>aria-label</code>s. Design context conveys visual structure only, never interaction.</li></ul><h2 id="state-deltas" tabindex="-1">State deltas <a class="header-anchor" href="#state-deltas" aria-label="Permalink to &quot;State deltas&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Background</th><th>Border</th></tr></thead><tbody><tr><td>Default</td><td><code>--ai-surface-primary</code></td><td>1px solid <code>--ai-border-secondary</code></td></tr><tr><td>Selected</td><td><code>--ai-surface-minimal</code></td><td>1px solid <code>--ai-border-brand</code></td></tr></tbody></table><p>Verified identical on both Type=Default (<code>3474:90673</code>) and Type=Full (<code>3474:90688</code>), so Selected composes as one modifier rather than branching per type.</p><h2 id="device-mobile-deltas" tabindex="-1">Device=Mobile deltas <a class="header-anchor" href="#device-mobile-deltas" aria-label="Permalink to &quot;Device=Mobile deltas&quot;">​</a></h2><p>Only four things change. Verified against the mobile Full variant (<code>3484:186649</code>) that buttons (24×24), badge and bar height (6px) all stay put between breakpoints.</p><table tabindex="0"><thead><tr><th>Property</th><th>Desktop</th><th>Mobile</th></tr></thead><tbody><tr><td>card <code>padding</code></td><td><code>--ai-spacing-5</code> (16px)</td><td><code>--ai-spacing-4</code> (12px)</td></tr><tr><td>card <code>min-inline-size</code></td><td><code>--ai-size-5</code> (280px)</td><td><code>--ai-size-4</code> (240px)</td></tr><tr><td>name <code>font-size</code></td><td><code>--ai-font-fixed-sm</code> (16px)</td><td><code>--ai-font-fixed-xs</code> (14px)</td></tr><tr><td>counts text</td><td><code>12 tables · 0/148 seated</code></td><td><code>12 tables · 0/148</code></td></tr></tbody></table><p>The counts change is <strong>content</strong>, which CSS can&#39;t do cleanly. <code>&quot; seated&quot;</code> is wrapped in <code>.room-card__seated</code> and clipped with <code>position: absolute; clip-path: inset(50%)</code> below 768px — visually gone, but still in the accessibility tree, so mobile screen-reader users hear the full sentence. <code>display: none</code> would have dropped it outright. Verified: the span measures 1px wide while <code>textContent</code> still reads <code>&quot;12 tables · 0/148 seated&quot;</code>.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code> / <code>--ai-surface-minimal</code></td><td><code>background-color</code></td><td>per state</td></tr><tr><td><code>--ai-border-secondary</code> / <code>--ai-border-brand</code></td><td><code>border-color</code></td><td>per state</td></tr><tr><td><code>--ai-radius-lg</code></td><td>card <code>border-radius</code> (16px)</td><td></td></tr><tr><td><code>light/shadow-xxs</code> → <code>--ai-shadow-xxs</code></td><td>card <code>box-shadow</code></td><td></td></tr><tr><td><code>--ai-spacing-5</code> / <code>--ai-spacing-4</code></td><td>card <code>padding</code> desktop / mobile</td><td></td></tr><tr><td><code>--ai-spacing-3</code></td><td>card <code>gap</code></td><td>header + meta <code>gap</code> too, but see below</td></tr><tr><td><code>--ai-spacing-1</code></td><td>actions <code>gap</code></td><td></td></tr><tr><td><code>--ai-size-5</code> / <code>--ai-size-4</code></td><td>card <code>min-inline-size</code> desktop / mobile</td><td></td></tr><tr><td><code>--ai-font-title</code></td><td>every text node</td><td></td></tr><tr><td><code>--ai-font-fixed-sm</code> / <code>-xs</code></td><td>name, desktop / mobile</td><td></td></tr><tr><td><code>--ai-font-fixed-2xs</code></td><td>counts (12px)</td><td></td></tr><tr><td><code>--ai-font-fixed-4xs</code></td><td>seats free (11px)</td><td></td></tr><tr><td><code>--ai-font-bold</code> / <code>-semibold</code> / <code>-regular</code></td><td>name / seats free / counts</td><td></td></tr><tr><td><code>--ai-text-primary</code> / <code>--ai-text-contrast</code></td><td>name / counts</td><td></td></tr><tr><td><code>--ai-text-brand</code></td><td>seats free</td><td>see below</td></tr><tr><td><code>--ai-surface-contrast</code></td><td>progress track</td><td></td></tr><tr><td><code>--ai-surface-brand</code></td><td>progress fill (Default, Seats Assigned)</td><td></td></tr><tr><td><code>--ai-surface-success</code></td><td>progress fill (Full)</td><td></td></tr><tr><td><code>--ai-radius-full</code></td><td>track, fill</td><td></td></tr><tr><td><code>--ai-spacing-2</code></td><td>track <code>block-size</code> (6px)</td><td></td></tr><tr><td><code>--ai-icon-size-xs</code></td><td>action-button icons (12px, via <code>btn--2xs</code>)</td><td></td></tr><tr><td><code>--ai-radius-sm</code></td><td>action-button radius (via <code>btn--2xs</code>)</td><td></td></tr></tbody></table><h2 id="two-gaps-where-the-css-leads-figma" tabindex="-1">Two gaps where the CSS leads Figma <a class="header-anchor" href="#two-gaps-where-the-css-leads-figma" aria-label="Permalink to &quot;Two gaps where the CSS leads Figma&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Property</th><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td><code>__header</code></td><td><code>gap</code></td><td><strong>not set</strong></td><td><code>--ai-spacing-3</code> (8px)</td></tr><tr><td><code>__meta</code></td><td><code>gap</code></td><td><strong>not set</strong></td><td><code>--ai-spacing-3</code> (8px)</td></tr></tbody></table><p><strong>The header gap was requested by the designer</strong> (2026-08-25). It matters more than it looks: <code>justify-content: space-between</code> gives no clearance once the name is long enough to fill its track, so a truncated name butted straight up against the edit button. Verified — the long-name demo card went from 0px of clearance to 8px.</p><p><strong>The badge&#39;s own divergences now live with the component.</strong> Its check icon was enlarged to 10×10 with <code>stroke-width: 4</code> and its label given <code>--ai-tracking-7</code>, both of which put it ~5px wider than the 45×15 Figma draws. Those are recorded in <code>FullBadge.figma-notes.md</code>, not here.</p><p><strong>The meta gap is not from Figma&#39;s meta frame</strong>, which sets none on any variant. The value came from the single-child badge wrapper (<code>3470:84968</code>) that was dropped as redundant, and is kept for the same reason as the header — clearance between the truncating counts and the seats-free label or badge.</p><p><strong>The two were matched at <code>--ai-spacing-3</code></strong> by the designer 2026-08-25 (the header started at 4px). Beyond consistency this buys real alignment: the actions cluster and the seats-free label now share a right edge, both landing 1px inside the card&#39;s padding box. Neither gap comes from Figma, so if the frames are ever updated, both rows want 8px.</p><h2 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h2><p>Resolved with the designer 2026-08-25 rather than invented. The badge&#39;s own gaps (the <code>border-3</code> gap, the 9px label, the 7×7 check, the <code>Grey/0</code> primitive) moved to <code>FullBadge.figma-notes.md</code> when it was extracted.</p><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td><code>--ai-surface-brand</code> bound as the &quot;N seats free&quot; <strong>text</strong> colour</td><td><strong>Rebound to <code>--ai-text-brand</code>.</strong> At 11px the surface token gives 3.60:1 on white and 3.44:1 on the Selected surface — both under the 4.5:1 AA floor. <code>--ai-text-brand</code> gives 5.04:1 / 4.82:1. <strong>Figma has been updated</strong>, and <code>3470:84948</code> already returns <code>--ai-text-brand</code>, so this is not a divergence.</td></tr><tr><td>card <code>width: 290px</code></td><td><strong>Dropped.</strong> The card is fluid and fills its column. 290px has no token; the bound <code>min-width</code> does (<code>--ai-size-5</code> / <code>--ai-size-4</code>), and those are kept.</td></tr></tbody></table><blockquote><p><strong><code>--ai-font-fixed-6xs</code> round-tripped cleanly.</strong> It was briefly hand-added to unblock this build; the designer&#39;s re-export landed the same day and <code>css/tokens.css</code> came back byte-identical, so the stopgap and the real variable agree. Worth knowing how the scale moved: the old 10px variable was <em>renamed</em> to <code>6xs</code> and set to 9, and a <strong>new</strong> variable (<code>VariableID:3532:102609</code>) took over <code>5xs</code> at 10px. So <code>--ai-font-fixed-5xs</code> still exists and AttendeeCard&#39;s seat badge is unaffected — but the ID reuse makes a naive id-based diff look like <code>5xs</code> vanished.</p></blockquote><h2 id="button-a-new-size-was-added-for-this-component" tabindex="-1">Button: a new size was added for this component <a class="header-anchor" href="#button-a-new-size-was-added-for-this-component" aria-label="Permalink to &quot;Button: a new size was added for this component&quot;">​</a></h2><p>Figma places the edit/delete actions as <strong>Button instances at 24×24</strong> with a 12px icon, but no existing size produced that: <code>btn--icon</code> is 40×40, <code>+ .btn--sm</code> 32×32, <code>+ .btn--xs</code> 32×24. At the designer&#39;s direction a new <code>.btn--icon.btn--2xs</code> was added to <code>Button.css</code> (24×24, 12px icon, <code>--ai-radius-sm</code>).</p><p>It is <strong>icon-only by design</strong> — there is no text <code>.btn--2xs</code>, because Figma defines none, and inventing one would be a variant with no Figma counterpart. AttendeeCard&#39;s action buttons have identical geometry (24px box, 12px icon, <code>--ai-radius-sm</code>) built as scoped <code>.attendee-card__action</code> CSS; folding those onto <code>btn--2xs</code> is a worthwhile follow-up but was out of scope here.</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li><strong>The action buttons are 24×24, well under the 44×44 minimum</strong> in CLAUDE.md §9. Built as drawn, matching the same decision taken for AttendeeCard, and recorded here for a later pass. The card&#39;s own select target is the full card, so the primary action is comfortably large.</li><li><strong>The progress bar is <code>aria-hidden</code>.</strong> &quot;12 tables · 124/148 seated&quot; and &quot;24 seats free&quot; state the same value in text immediately above it; a <code>progressbar</code> role would make screen readers announce the number a third time.</li><li>The FULL badge&#39;s white-on-success contrast (3.16:1) is <strong>deliberately open</strong> at the designer&#39;s direction — see <code>FullBadge.figma-notes.md</code>. It is a palette problem, not a card problem.</li><li>The room name is an <code>&lt;h3&gt;</code>; the demo nests it under <code>&lt;h2&gt;</code> section headings.</li></ul><h2 id="responsive-container-queries-2026-08-27" tabindex="-1">Responsive: container queries (2026-08-27) <a class="header-anchor" href="#responsive-container-queries-2026-08-27" aria-label="Permalink to &quot;Responsive: container queries (2026-08-27)&quot;">​</a></h2><p><strong>Keys on <code>cs-page</code>, NOT a self-container.</strong> Measured own width <strong>280px</strong> desktop / ~302px mobile — both under 767, so a self-query would fire permanently. Same reasoning as TableCard.</p><p>Rationale and the decision rule live in <strong>CLAUDE.md §4a</strong>. The short version: a docked SidebarMenu shrinks the CC content column with no window resize, so a viewport query cannot see the real available width — measured 820px of column at a 2239px viewport, with no query firing.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong><code>Full-Badge</code> is an inline frame in Figma, not a component instance</strong> — <code>get_metadata</code> reports it as <code>&lt;frame&gt;</code> where the two Buttons report as <code>&lt;instance&gt;</code>. It was originally scoped here as <code>.room-card__badge</code>, then <strong>extracted to <code>src/components/FullBadge/</code> on 2026-08-25</strong> once TableCard turned out to draw an identical copy. Figma should follow by making it a real component; until then neither consumer can Code Connect it.</li><li><strong><code>get_design_context</code> returns the actions frame as an empty <code>&lt;div&gt;</code></strong> on every variant — the Button instances are flattened out of the output. They are only visible via <code>get_metadata</code> on the frame. Don&#39;t read that empty div as &quot;no actions&quot;; the screenshot shows two.</li><li><strong>Design context under-reports bound tokens.</strong> The title&#39;s size renders as raw <code>text-[16px]</code> and the min-width as <code>min-w-[280px]</code>, but <code>get_variable_defs</code> shows both bound (<code>--ai-font-fixed-sm</code>, <code>--ai-size-5</code>). Always cross-check the two before flagging a gap.</li><li><strong>A single-child flex wrapper around the badge</strong> (<code>3470:84968</code>, gap <code>--ai-spacing-3</code>) is dropped — a gap on a one-child flex container does nothing.</li><li><strong>No hover, focus, pressed or disabled variants</strong> exist in the Figma set. The action buttons get Button&#39;s own states; nothing else was invented.</li><li><strong>No dark-mode variant</strong> in Figma. Every colour is a theme-aware <code>--ai-*</code> token, so the card will re-resolve under <code>[data-theme=&quot;dark&quot;]</code>, but that has not been designed or reviewed.</li><li><code>font-semibold</code> on the seats-free text is unbound in Figma while its siblings cite <code>--ai-font-bold</code> / <code>--ai-font-regular</code>. <code>--ai-font-semibold</code> (600) is used here. <strong>Worth binding in Figma.</strong></li></ul><hr><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=3470-84951" target="_blank" rel="noreferrer">Open in Figma</a></p>',47))])}const v=n(h,[["render",g]]);export{y as __pageData,v as default};
